// Clean every cache layer except user data, then do a from-scratch production build.
//
// What is cleared:
//   .output              build output (rebuilt below)
//   node_modules/.vite   Vite dependency pre-bundle cache
//   node_modules/.nitro  Nitro build cache
//   .tanstack            router codegen cache
//   src/paraglide        generated i18n runtime (regenerated by `pnpm build`)
//   src/routeTree.gen.ts generated route tree (regenerated by vite build)
//
// What is NOT touched, on purpose:
//   data/                projects, generations, uploaded media, SQLite database
//   public/              static assets that are part of the app
//   E:\ComfyUI           models and custom nodes
//
// The services are stopped for the rebuild because the running server holds a
// lock on .output/server/node_modules/@libsql/.../index.node, and the build fails
// with EPERM if it is not released first.
import { spawnSync } from 'node:child_process';
import { existsSync, readdirSync, rmSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const NODE_DIR = 'C:\\Program Files\\nodejs';
const PNPM = 'C:\\Program Files\\nodejs\\pnpm.cmd';

const CACHE_PATHS = [
  '.output',
  'node_modules/.vite',
  'node_modules/.nitro',
  '.tanstack',
  'src/paraglide',
  'src/routeTree.gen.ts',
];

const run = (cmd, args, label, { allowFailure = false } = {}) => {
  console.log(`\n> ${label}`);
  const r = spawnSync(cmd, args, {
    cwd: ROOT,
    stdio: 'inherit',
    shell: false,
    env: { ...process.env, CI: 'true', PATH: `${NODE_DIR};${process.env.PATH}` },
  });
  if (r.status !== 0) {
    if (allowFailure) {
      console.log('  - 跳过（本步为尽力而为）');
      return;
    }
    console.error(`  ✗ 失败（exit ${r.status}）`);
    process.exit(r.status ?? 1);
  }
  console.log('  ✓ 完成');
};

const sizeOf = (p) => {
  if (!existsSync(p)) return null;
  const s = statSync(p);
  if (!s.isDirectory()) return s.size;
  let total = 0;
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else {
        try {
          total += statSync(full).size;
        } catch {
          // Files can disappear mid-walk; the total is informational only.
        }
      }
    }
  };
  walk(p);
  return total;
};

const mb = (n) => `${(n / 1024 / 1024).toFixed(1)} MB`;

// ── 1. 停服务
run('schtasks', ['/end', '/tn', 'BD-Workbench'], '停止工作台任务', {
  allowFailure: true,
});
// The task only ends cmd.exe; node keeps the port and the file lock. Harmless
// when the port is already free, which is why failure is tolerated.
run(
  'powershell',
  ['-NoProfile', '-Command',
    "Get-NetTCPConnection -State Listen -LocalPort 3020 -ErrorAction SilentlyContinue | " +
    "Select-Object -First 1 | ForEach-Object { taskkill /PID $($_.OwningProcess) /T /F }"],
  '释放 3020 端口',
  { allowFailure: true }
);

// ── 2. 删缓存
console.log('\n> 清理缓存目录');
for (const rel of CACHE_PATHS) {
  const abs = join(ROOT, rel);
  if (!existsSync(abs)) {
    console.log(`  - ${rel}（不存在）`);
    continue;
  }
  const before = sizeOf(abs);
  rmSync(abs, { recursive: true, force: true });
  console.log(`  ✓ ${rel}${before !== null ? `  释放 ${mb(before)}` : ''}`);
}

// ── 3. 从零构建
// pnpm.cmd is a batch file: on Windows it has to go through cmd.exe, because
// spawnSync cannot execute a .cmd directly without a shell.
run('cmd.exe', ['/c', PNPM, 'run', 'build'], '生产构建（含 paraglide / routeTree 重新生成）');

// ── 4. 起服务
run('schtasks', ['/run', '/tn', 'BD-Workbench'], '启动工作台任务');

// ── 5. 等就绪
console.log('\n> 等待工作台就绪');
let ready = false;
for (let i = 0; i < 40; i++) {
  await new Promise((r) => setTimeout(r, 1500));
  try {
    const res = await fetch('http://127.0.0.1:3020/zh', { signal: AbortSignal.timeout(3000) });
    if (res.ok) {
      ready = true;
      break;
    }
  } catch {
    // Still starting.
  }
}
console.log(ready ? '  ✓ 工作台已就绪' : '  ✗ 未能就绪，请查看 data\\logs\\workbench.err.log');

// ── 6. 确认 HTML 不再被浏览器启发式缓存
try {
  const res = await fetch('http://127.0.0.1:3020/zh', { signal: AbortSignal.timeout(5000) });
  const cc = res.headers.get('cache-control');
  console.log(`\n  页面 Cache-Control: ${cc ?? '(无)'}`);
} catch {
  // Ignore: reported above.
}

console.log(`
浏览器端还需要硬刷新一次（服务端缓存已清空，但浏览器里旧的 HTML 还在）：
  · 当前页面按 Ctrl + F5，或
  · F12 打开开发者工具 → 右键刷新按钮 → 「清空缓存并硬性重新加载」
之后因为 HTML 现在带 no-cache，正常刷新就会重新校验，不会再吃到旧页面。
`);
